import { Note, FretNode, Tuning } from "./theory";
import type { Fingering } from "./theory";
import { findValidPaths } from "./fingering-search";

export const DEFAULT_SCALE_LENGTH = 650;
export const FRET_SCALE_DIVISOR = 17.817; // "Rule of 18"
export const MAX_FRET_SPAN = 5;

/** All orderings of `items` (port of itertools.permutations). Empty -> [[]]. */
function permutations<T>(items: T[]): T[][] {
  if (items.length <= 1) {
    return [items.slice()];
  }
  const result: T[][] = [];
  for (let i = 0; i < items.length; i++) {
    const rest = [...items.slice(0, i), ...items.slice(i + 1)];
    for (const perm of permutations(rest)) {
      result.push([items[i], ...perm]);
    }
  }
  return result;
}

/** First-wins dedup by pitch (port of midi_utils.remove_duplicate_notes). */
function removeDuplicateNotes(notes: Note[]): Note[] {
  const seen = new Set<number>();
  const result: Note[] = [];
  for (const note of notes) {
    if (!seen.has(note.pitch)) {
      seen.add(note.pitch);
      result.push(note);
    }
  }
  return result;
}

/**
 * Octave-fold a single pitch into [minPitch, maxPitch]. Returns the folded pitch,
 * or null if it still falls outside the range afterward. Equivalent to the
 * per-note logic of fixOobNotes(preserveHighest=false).
 */
export function foldPitchToRange(pitch: number, minPitch: number, maxPitch: number): number | null {
  let octaves = 0;
  if (pitch > maxPitch) {
    octaves = -Math.ceil(Math.max(pitch - maxPitch, 0) / 12);
  }
  if (pitch < minPitch) {
    octaves = Math.ceil(Math.max(minPitch - pitch, 0) / 12);
  }
  const folded = pitch + octaves * 12;
  return folded >= minPitch && folded <= maxPitch ? folded : null;
}

export class Fretboard {
  readonly tuning: Tuning;
  readonly nstrings: number;
  readonly scaleLength = DEFAULT_SCALE_LENGTH;
  readonly nodes: FretNode[] = [];
  readonly fingeringCache = new Map<string, Fingering[]>();
  private readonly pitchIndex = new Map<number, FretNode[]>();

  constructor(tuning: Tuning) {
    this.tuning = tuning;
    this.nstrings = tuning.nstrings;
    let id = 0;
    tuning.strings.forEach((string, istring) => {
      for (let ifret = 0; ifret <= tuning.nfrets; ifret++) {
        const node = new FretNode(string.pitch + ifret, id++, istring, ifret);
        this.nodes.push(node);
        const bucket = this.pitchIndex.get(node.pitch);
        if (bucket) {
          bucket.push(node);
        } else {
          this.pitchIndex.set(node.pitch, [node]);
        }
      }
    });
  }

  getSpecificNoteOptions(note: Note): FretNode[] {
    return this.pitchIndex.get(note.pitch) ?? [];
  }

  getNoteOptions(notes: Note[]): FretNode[][] {
    return notes.map((note) => this.getSpecificNoteOptions(note)).filter((arr) => arr.length > 0);
  }

  /** Geometry distance between two (string, fret) points, strings normalized by nstrings. */
  distanceBetween(p1: [number, number], p2: [number, number]): number {
    return Math.hypot(p1[0] / this.nstrings - p2[0] / this.nstrings, p1[1] - p2[1]);
  }

  /** Distance of a fret from the nut ("rule of 18"). */
  getFretDistance(nfret: number): number {
    let result = 0;
    let remaining = this.scaleLength;
    for (let i = 0; i < nfret; i++) {
      const fretHeight = remaining / FRET_SCALE_DIVISOR;
      result += fretHeight;
      remaining -= fretHeight;
    }
    return result;
  }

  getPossibleFingerings(noteOptions: FretNode[][]): Fingering[] {
    const cacheKey = [...new Set(noteOptions.map((opts) => opts[0].pitch))]
      .sort((a, b) => a - b)
      .join(",");
    const cached = this.fingeringCache.get(cacheKey);
    if (cached) {
      return cached;
    }

    let fingerings: Fingering[] = [];
    if (noteOptions.length === 1) {
      fingerings = noteOptions[0].map((note) => [note]);
    } else if (noteOptions.length > 1) {
      const seen = new Set<string>();
      for (const permutation of permutations(noteOptions)) {
        for (const path of findValidPaths(permutation, this.nstrings)) {
          const key = path.map((n) => n.id).sort((a, b) => a - b).join(",");
          if (!seen.has(key) && this.isFingeringPossible(path, permutation)) {
            seen.add(key);
            fingerings.push(path);
          }
        }
      }
    }

    this.fingeringCache.set(cacheKey, fingerings);
    return fingerings;
  }

  isFingeringPossible(fingering: Fingering, noteArrays: FretNode[][]): boolean {
    const strings = fingering.map((n) => n.string);
    const onePerString = new Set(strings).size === strings.length;

    // Strict `< MAX_FRET_SPAN` and `length <= noteArrays.length` mirror tuttut's
    // is_fingering_possible exactly (parity — do not relax to <= / ===).
    const usedFrets = fingering.map((n) => n.fret).filter((f) => f !== 0);
    const spanOk =
      usedFrets.length > 0 ? Math.max(...usedFrets) - Math.min(...usedFrets) < MAX_FRET_SPAN : true;

    const rightLength = fingering.length <= noteArrays.length;

    return onePerString && spanOk && rightLength;
  }

  fixOobNotes(notes: Note[], preserveHighest = false): Note[] {
    const [minPitch, maxBound] = this.tuning.getPitchBounds();
    let maxPitch = maxBound;

    if (preserveHighest) {
      const highestBefore = Math.max(...notes.map((n) => n.pitch));
      let highestAfter: number;
      if (highestBefore > maxPitch) {
        const above = Math.max(highestBefore - maxPitch, 0);
        highestAfter = highestBefore - Math.ceil(above / 12) * 12;
      } else {
        const below = Math.max(minPitch - highestBefore, 0);
        highestAfter = highestBefore + Math.ceil(below / 12) * 12;
      }
      maxPitch = highestAfter;
    }

    const result: Note[] = [];
    for (const note of notes) {
      const folded = foldPitchToRange(note.pitch, minPitch, maxPitch);
      if (folded !== null) {
        result.push(new Note(folded));
      }
    }
    return removeDuplicateNotes(result);
  }
}
