import { precomputeFingeringStats, getDheightScore, laplaceDistro } from "./difficulty";
import type { FingeringStats } from "./difficulty";
import type { Fingering, Tuning } from "./theory";
import type { DifficultyWeights } from "./types";

/** Normalize an array of values into a probability distribution (sum 1). */
export function difficultiesToProbabilities(values: number[]): number[] {
  const total = values.reduce((a, b) => a + b, 0);
  return values.map((v) => v / total);
}

/**
 * Append a new chord's fingerings to the emission matrix as a new block column.
 * Final shape: (nFingerings, nObservedChords). New rows emit only the new column.
 * Port of graph_utils.expand_emission_matrix.
 */
export function expandEmissionMatrix(emission: number[][], newFingeringCount: number): number[][] {
  if (emission.length > 0) {
    const oldCols = emission[0].length;
    const result = emission.map((row) => [...row, 0]);
    for (let i = 0; i < newFingeringCount; i++) {
      result.push([...new Array<number>(oldCols).fill(0), 1]);
    }
    return result;
  }
  return Array.from({ length: newFingeringCount }, () => [1]);
}

/** First-max argmax (matches numpy.argmax tie-breaking). */
function argmax(values: number[]): number {
  let best = -Infinity;
  let bestIndex = 0;
  for (let i = 0; i < values.length; i++) {
    if (values[i] > best) {
      best = values[i];
      bestIndex = i;
    }
  }
  return bestIndex;
}

/**
 * Log-space Viterbi. A negative observation indexes the emission column from the
 * end (numpy negative-index semantics): obs < 0 -> obs + nCols. Port of graph_utils.viterbi.
 */
export function viterbi(
  observations: number[],
  Tm: number[][],
  Em: number[][],
  initial: number[],
): number[] {
  const T = observations.length;
  const M = Tm.length;
  const nCols = Em[0].length;
  const column = (t: number): number => {
    const obs = observations[t];
    return obs < 0 ? obs + nCols : obs;
  };

  const logTm = Tm.map((row) => row.map((v) => Math.log(v)));
  const logEm = Em.map((row) => row.map((v) => Math.log(v)));

  const omega: number[][] = Array.from({ length: T }, () => new Array<number>(M).fill(0));
  for (let i = 0; i < M; i++) {
    omega[0][i] = Math.log(initial[i]) + logEm[i][column(0)];
  }

  const prev: number[][] = Array.from({ length: Math.max(0, T - 1) }, () =>
    new Array<number>(M).fill(0),
  );

  for (let t = 1; t < T; t++) {
    const c = column(t);
    for (let j = 0; j < M; j++) {
      let best = -Infinity;
      let bestIndex = 0;
      for (let i = 0; i < M; i++) {
        const score = omega[t - 1][i] + logTm[i][j] + logEm[j][c];
        if (score > best) {
          best = score;
          bestIndex = i;
        }
      }
      omega[t][j] = best;
      prev[t - 1][j] = bestIndex;
    }
  }

  const states = new Array<number>(T).fill(0);
  let last = argmax(omega[T - 1]);
  states[0] = last;
  let backtrackIndex = 1;
  for (let i = T - 2; i >= 0; i--) {
    const state = prev[i][last];
    states[backtrackIndex] = state;
    last = state;
    backtrackIndex++;
  }

  return states.reverse();
}

function intersectionSize(a: Set<number>, b: Set<number>): number {
  let n = 0;
  a.forEach((x) => {
    if (b.has(x)) n++;
  });
  return n;
}

/** Easiness of transitioning prev -> curr (higher = easier). Port of _compute_pair_easiness. */
function computePairEasiness(
  curr: FingeringStats,
  prev: FingeringStats,
  weights: DifficultyWeights,
  tuning: Tuning,
): number {
  const currRawHeight = curr.rawHeight !== 0 ? curr.rawHeight : prev.rawHeight;
  const dheight = getDheightScore(currRawHeight, prev.rawHeight, tuning);
  const nChanged =
    (curr.nNotes - intersectionSize(curr.allStrings, prev.nonOpenStrings)) / tuning.nstrings;

  return (
    laplaceDistro(dheight, weights.b) *
    (1 / (1 + curr.heightScore * weights.height)) *
    (1 / (1 + curr.spanScore * weights.length)) *
    (1 / (1 + nChanged * weights.nChangedStrings))
  );
}

/**
 * Transition matrix over all fingerings. Each row is the easiness of moving from
 * the previous fingering to every current fingering, normalized to a distribution
 * (higher easiness -> higher transition probability). Port of build_transition_matrix.
 */
export function buildTransitionMatrix(
  fingerings: Fingering[],
  weights: DifficultyWeights,
  tuning: Tuning,
): number[][] {
  const n = fingerings.length;
  const stats = precomputeFingeringStats(fingerings, tuning);
  const transition: number[][] = [];
  for (let iprev = 0; iprev < n; iprev++) {
    const easiness = stats.map((_, icurr) =>
      computePairEasiness(stats[icurr], stats[iprev], weights, tuning),
    );
    transition.push(difficultiesToProbabilities(easiness));
  }
  return transition;
}
