const SEMITONES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

/** Mirrors pretty_midi.note_number_to_name. `pitch` is an integer MIDI note number. octave = floor(pitch/12) - 1. */
export function noteNumberToName(pitch: number): string {
  if (!Number.isInteger(pitch)) {
    throw new Error(`pitch must be an integer MIDI note number, got ${pitch}`);
  }
  const octave = Math.floor(pitch / 12) - 1;
  const semitone = SEMITONES[((pitch % 12) + 12) % 12];
  return `${semitone}${octave}`;
}

const PITCH_MAP: Record<string, number> = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
const ACCIDENTAL_MAP: Record<string, number> = { "#": 1, "": 0, b: -1, "!": -1 };

/** Mirrors pretty_midi.note_name_to_number. */
export function noteNameToNumber(name: string): number {
  const match = /^([A-Ga-g])([#b!]?)([+-]?\d+)$/.exec(name);
  if (!match) {
    throw new Error(`Invalid note name: ${name}`);
  }
  const pitch = PITCH_MAP[match[1].toUpperCase()];
  const offset = ACCIDENTAL_MAP[match[2]];
  const octave = parseInt(match[3], 10);
  return 12 * (octave + 1) + pitch + offset;
}

export class Note {
  readonly pitch: number;
  readonly name: string;
  readonly degree: string;
  readonly octave: string;

  constructor(pitch: number) {
    this.pitch = pitch;
    this.name = noteNumberToName(pitch);
    // Reproduce Python's name[:-1] / name[-1] slicing exactly, incl. the "C-1" quirk.
    this.degree = this.name.slice(0, -1);
    this.octave = this.name.slice(-1);
  }
}

/** A fretboard position. Carries its own (string, fret) and a stable id, replacing Python's positions dict + identity hashing. */
export class FretNode extends Note {
  readonly id: number;
  readonly string: number;
  readonly fret: number;

  constructor(pitch: number, id: number, string: number, fret: number) {
    super(pitch);
    this.id = id;
    this.string = string;
    this.fret = fret;
  }
}

/** A chosen set of fretboard positions for one chord/onset (a path through note options). */
export type Fingering = FretNode[];

export class Tuning {
  static readonly STANDARD_GUITAR = ["E4", "B3", "G3", "D3", "A2", "E2"];
  static readonly STANDARD_UKULELE = ["A4", "E4", "C4", "G4"];

  readonly strings: Note[];
  readonly nstrings: number;
  readonly nfrets: number;

  constructor(stringNames: string[] = Tuning.STANDARD_GUITAR, nfrets = 20) {
    this.strings = stringNames.map((name) => new Note(noteNameToNumber(name)));
    this.nstrings = stringNames.length;
    this.nfrets = nfrets;
  }

  static standardGuitar(): Tuning {
    return new Tuning(Tuning.STANDARD_GUITAR);
  }

  static ukulele(): Tuning {
    return new Tuning(Tuning.STANDARD_UKULELE);
  }

  getAllPossibleNotes(): Note[][] {
    return this.strings.map((string) => {
      const stringNotes: Note[] = [];
      for (let fret = 0; fret <= this.nfrets; fret++) {
        stringNotes.push(new Note(string.pitch + fret));
      }
      return stringNotes;
    });
  }

  getPitchBounds(): [number, number] {
    const pitches = this.strings.map((s) => s.pitch);
    return [Math.min(...pitches), Math.max(...pitches) + this.nfrets];
  }
}
