import type { Fingering, Tuning } from "./theory";
import type { DifficultyWeights } from "./types";

export const SPAN_NORMALIZATION = 5;

/** Laplace distribution value at x. `b` is the scale parameter; must be > 0. */
export function laplaceDistro(x: number, b: number, mu = 0): number {
  return (1 / (2 * b)) * Math.exp(-Math.abs(x - mu) / b);
}

// NOTE: getNfingers, computePathDifficulty, and getNChangedStrings are kept for
// parity with tuttut's difficulty.py and its unit tests, but are NOT on the live
// transition path — the engine uses computePairEasiness in hmm.ts (over precomputed
// stats) instead. Keep them in sync with the Python reference, don't delete as "dead".
/** Number of fretted (non-open) notes in a path. */
export function getNfingers(path: Fingering): number {
  return path.filter((n) => n.fret !== 0).length;
}

/** Average of highest & lowest non-open fret. Falls back to previousPath when all-open. */
export function getRawHeight(path: Fingering, previousPath?: Fingering): number {
  const frets = path.filter((n) => n.fret !== 0).map((n) => n.fret);
  if (frets.length > 0) {
    return (Math.max(...frets) + Math.min(...frets)) / 2;
  }
  if (previousPath === undefined) {
    return 0;
  }
  return getRawHeight(previousPath);
}

export function getHeightScore(rawHeight: number, tuning: Tuning): number {
  return rawHeight / tuning.nfrets;
}

export function getDheightScore(height: number, previousHeight: number, tuning: Tuning): number {
  return Math.abs(height - previousHeight) / tuning.nfrets;
}

export function getPathSpan(path: Fingering): number {
  const frets = path.filter((n) => n.fret !== 0).map((n) => n.fret);
  return frets.length > 0 ? (Math.max(...frets) - Math.min(...frets)) / SPAN_NORMALIZATION : 0;
}

export function getNChangedStrings(path: Fingering, previousPath: Fingering, tuning: Tuning): number {
  const used = new Set(path.map((n) => n.string));
  const previousUsed = new Set(previousPath.filter((n) => n.fret !== 0).map((n) => n.string));
  let intersection = 0;
  used.forEach((s) => {
    if (previousUsed.has(s)) intersection++;
  });
  return (path.length - intersection) / tuning.nstrings;
}

export interface FingeringStats {
  rawHeight: number;
  heightScore: number;
  spanScore: number;
  allStrings: Set<number>;
  nonOpenStrings: Set<number>;
  nNotes: number;
}

export function precomputeFingeringStats(fingerings: Fingering[], tuning: Tuning): FingeringStats[] {
  return fingerings.map((fingering) => {
    const rawHeight = getRawHeight(fingering);
    return {
      rawHeight,
      heightScore: getHeightScore(rawHeight, tuning),
      spanScore: getPathSpan(fingering),
      allStrings: new Set(fingering.map((n) => n.string)),
      nonOpenStrings: new Set(fingering.filter((n) => n.fret !== 0).map((n) => n.string)),
      nNotes: fingering.length,
    };
  });
}

/** Difficulty of a path ignoring the previous shape. */
export function computeIsolatedPathDifficulty(path: Fingering, tuning: Tuning): number {
  const rawHeight = getRawHeight(path);
  const height = getHeightScore(rawHeight, tuning);
  const span = getPathSpan(path);
  const easiness = (1 / (1 + height)) * (1 / (1 + span));
  return 1 / easiness;
}

/** Difficulty of transitioning from previousPath to path. */
export function computePathDifficulty(
  path: Fingering,
  previousPath: Fingering,
  weights: DifficultyWeights,
  tuning: Tuning,
): number {
  const rawHeight = getRawHeight(path, previousPath);
  const previousRawHeight = previousPath.length > 0 ? getRawHeight(previousPath) : 0;
  const height = getHeightScore(rawHeight, tuning);
  const dheight = getDheightScore(rawHeight, previousRawHeight, tuning);
  const span = getPathSpan(path);
  const nChangedStrings = getNChangedStrings(path, previousPath, tuning);

  const easiness =
    laplaceDistro(dheight, weights.b) *
    (1 / (1 + height * weights.height)) *
    (1 / (1 + span * weights.length)) *
    (1 / (1 + nChangedStrings * weights.nChangedStrings));

  return 1 / easiness;
}
