import { Note, Tuning } from "./theory";
import type { Fingering } from "./theory";
import { Fretboard, foldPitchToRange } from "./fretboard";
import { computeIsolatedPathDifficulty } from "./difficulty";
import {
  buildTransitionMatrix,
  difficultiesToProbabilities,
  expandEmissionMatrix,
  viterbi,
} from "./hmm";
import { DEFAULT_TIME_SIGNATURE, DEFAULT_WEIGHTS } from "./types";
import type {
  NoteModel,
  QuantizeGrid,
  TabData,
  TabEvent,
  TabInput,
  TimeSignatureChange,
} from "./types";

const BEAT_EPSILON = 1e-6;
const GRID_BEATS: Record<QuantizeGrid, number> = {
  "1/4": 1,
  "1/8": 0.5,
  "1/16": 0.25,
  "1/32": 0.125,
};

/** Measure length in quarter-note beats. Replaces measure_length_ticks. */
export function measureLengthBeats(ts: { numerator: number; denominator: number }): number {
  return (ts.numerator * 4) / ts.denominator;
}

function roundKey(beats: number): number {
  return Math.round(beats / BEAT_EPSILON) * BEAT_EPSILON;
}

interface TimelineEntry {
  beats: number;
  notes?: NoteModel[];
  timeSignature?: TimeSignatureChange;
}

function buildTimeline(
  notes: NoteModel[],
  timeSignatures: TimeSignatureChange[],
  quantizeGrid: QuantizeGrid | undefined,
): TimelineEntry[] {
  const grid = quantizeGrid ? GRID_BEATS[quantizeGrid] : undefined;
  const snap = (b: number): number => (grid ? Math.round(b / grid) * grid : b);
  const map = new Map<number, TimelineEntry>();

  const sorted = [...notes].sort((a, b) => a.startBeats - b.startBeats || a.midi - b.midi);
  for (const note of sorted) {
    const onset = snap(note.startBeats);
    const key = roundKey(onset);
    let entry = map.get(key);
    if (!entry) {
      entry = { beats: onset };
      map.set(key, entry);
    }
    if (entry.notes) {
      entry.notes.push(note);
    } else {
      entry.notes = [note];
    }
  }

  for (const ts of timeSignatures) {
    const key = roundKey(ts.startBeats);
    let entry = map.get(key);
    if (!entry) {
      entry = { beats: ts.startBeats };
      map.set(key, entry);
    }
    entry.timeSignature = ts;
  }

  return [...map.values()].sort((a, b) => a.beats - b.beats);
}

interface MeasureWindow {
  start: number;
  end: number;
  entries: TimelineEntry[];
}

function buildMeasures(
  timeline: TimelineEntry[],
  timeSignatures: TimeSignatureChange[],
  totalBeats: number,
): MeasureWindow[] {
  const sortedTs = [...timeSignatures].sort((a, b) => a.startBeats - b.startBeats);
  const measures: MeasureWindow[] = [];

  for (let i = 0; i < sortedTs.length; i++) {
    const segStart = sortedTs[i].startBeats;
    const segEnd = i < sortedTs.length - 1 ? sortedTs[i + 1].startBeats : totalBeats;
    const length = measureLengthBeats(sortedTs[i]);
    if (length <= 0) {
      continue;
    }
    for (let mStart = segStart; mStart < segEnd - BEAT_EPSILON; mStart += length) {
      const mEnd = Math.min(mStart + length, segEnd);
      const entries = timeline.filter(
        (e) => e.beats >= mStart - BEAT_EPSILON && e.beats < mEnd - BEAT_EPSILON,
      );
      measures.push({ start: mStart, end: mEnd, entries });
    }
  }

  return measures;
}

export interface AsciiRenderOptions {
  /** Wrap into stacked systems no wider than this many columns.
   *  Omitted or <= 0 ⇒ a single unwrapped system (legacy behavior). */
  maxWidth?: number;
  /** Render the time signature at the first system and at each change.
   *  Default false (preserves legacy output). */
  timeSignature?: boolean;
}

/** One measure's body (no header): `nstrings` equal-length rows. `cellWidth` is
 *  the global max fret-digit width so multi-digit frets never skew the grid. */
function renderMeasureBody(
  measure: TabData["measures"][number],
  nstrings: number,
  cellWidth: number,
  showTimeSignature: boolean,
): string[] {
  const rows = Array.from({ length: nstrings }, () => "");

  if (showTimeSignature) {
    const tsEvent = measure.events.find((e) => e.timeSignatureChange);
    if (tsEvent) {
      const [num, den] = tsEvent.timeSignatureChange!;
      if (nstrings === 1) {
        // No rows to stack on a 1-string tuning: render inline, e.g. "4/4".
        rows[0] += `${num}/${den}`;
      } else {
        const tw = Math.max(String(num).length, String(den).length);
        const upper = Math.floor(nstrings / 2) - 1; // numerator row
        const lower = Math.floor(nstrings / 2); // denominator row
        for (let s = 0; s < nstrings; s++) {
          const cell = s === upper ? String(num) : s === lower ? String(den) : "";
          rows[s] += cell.padEnd(tw, "-");
        }
      }
    }
  }

  const events = measure.events;
  for (let ievent = 0; ievent < events.length; ievent++) {
    const event = events[ievent];
    if (!event.notes) {
      continue; // time-signature / marker events don't take a column
    }
    for (let s = 0; s < nstrings; s++) {
      const note = event.notes.find((n) => n.string === s);
      rows[s] += note ? String(note.fret).padEnd(cellWidth, "-") : "-".repeat(cellWidth);
    }
    const nextTiming = ievent < events.length - 1 ? events[ievent + 1].measureTiming : 1.0;
    // *16 = 16th-note resolution: at most 16 dash positions per measure (parity with tuttut).
    const dashes = Math.max(1, Math.floor((nextTiming - event.measureTiming) * 16));
    for (let s = 0; s < nstrings; s++) rows[s] += "-".repeat(dashes);
  }

  return rows;
}

/**
 * Render `data` as ASCII tablature, one string-line block per "system".
 * - Cells use a uniform width (the global max fret-digit count) so multi-digit
 *   frets never skew the beat grid.
 * - With `maxWidth`, measures are packed into stacked systems no wider than
 *   `maxWidth`; a measure is never split (a lone over-wide measure overflows).
 * - With `timeSignature`, a stacked time signature is shown at the first system
 *   and wherever the signature changes.
 */
export function renderAsciiTab(
  data: TabData,
  tuning: Tuning,
  opts: AsciiRenderOptions = {},
): string[][] {
  const nstrings = tuning.nstrings;

  let cellWidth = 1;
  for (const measure of data.measures)
    for (const event of measure.events)
      if (event.notes)
        for (const note of event.notes)
          cellWidth = Math.max(cellWidth, String(note.fret).length);

  const headers = tuning.strings.map((s) => {
    const header = s.degree;
    return header + (header.length > 1 ? "||" : " ||");
  });
  const headerWidth = headers[0].length;

  const bodies = data.measures.map((m) =>
    renderMeasureBody(m, nstrings, cellWidth, !!opts.timeSignature),
  );
  const measureWidths = bodies.map((b) => b[0].length + 1); // + trailing "|"

  const systems: string[][] = [];
  let cur = headers.slice();
  let curWidth = headerWidth;
  let count = 0;
  for (let m = 0; m < bodies.length; m++) {
    const w = measureWidths[m];
    if (opts.maxWidth && opts.maxWidth > 0 && count > 0 && curWidth + w > opts.maxWidth) {
      systems.push(cur);
      cur = headers.slice();
      curWidth = headerWidth;
      count = 0;
    }
    for (let s = 0; s < nstrings; s++) cur[s] += bodies[m][s] + "|";
    curWidth += w;
    count++;
  }
  systems.push(cur);
  return systems;
}

/** Flatten systems into lines; a blank line separates stacked systems. */
function renderLines(data: TabData, tuning: Tuning, opts: AsciiRenderOptions = {}): string[] {
  return renderAsciiTab(data, tuning, opts).flatMap((sys, i) => (i > 0 ? ["", ...sys] : sys));
}

export interface GeneratedTab {
  data: TabData;
  toSystems(opts?: AsciiRenderOptions): string[][];
  toLines(opts?: AsciiRenderOptions): string[];
  toAscii(opts?: AsciiRenderOptions): string;
}

/**
 * Generate a tab from beat-based notes.
 *
 * Contract notes:
 * - Notes whose onset falls before the first `timeSignatures` entry's
 *   `startBeats` are ignored: the measure grid only starts at the first time
 *   signature (the default grid starts at beat 0, so this only affects callers
 *   passing a custom grid that starts later, or negative onsets).
 * - Chords with no physically possible fingering produce an event whose
 *   `notes` is an empty array (see "Divergences from tuttut" in the README).
 * - `durationBeats` is carried through untouched, including 0 or negative
 *   values; a note is never dropped for having a degenerate duration.
 * - Throws if `weights.b` is not a positive number (Laplace scale parameter).
 */
export function generateTab(input: TabInput): GeneratedTab {
  const tuning = input.tuning;
  const weights = input.weights ?? DEFAULT_WEIGHTS;
  if (!(weights.b > 0)) {
    throw new Error(`weights.b must be a positive Laplace scale parameter, got ${weights.b}`);
  }
  const timeSignatures =
    input.timeSignatures && input.timeSignatures.length > 0
      ? input.timeSignatures
      : [DEFAULT_TIME_SIGNATURE];
  const fretboard = new Fretboard(tuning);
  const [minPitch, maxPitch] = tuning.getPitchBounds();

  const timeline = buildTimeline(input.notes, timeSignatures, input.quantizeGrid);
  // Clip end, computed from SNAPPED onsets so quantization can't push a note
  // past it (DIVERGENCE from tuttut, which derives it from raw note ends).
  // Each onset also gets a hair of padding past itself so zero- or negative-
  // duration notes at the exact clip end still land inside the half-open
  // final measure window instead of being silently dropped.
  let totalBeats = 0;
  for (const entry of timeline) {
    if (!entry.notes) continue;
    for (const n of entry.notes) {
      totalBeats = Math.max(totalBeats, entry.beats + Math.max(n.durationBeats, 0));
    }
    totalBeats = Math.max(totalBeats, entry.beats + 2 * BEAT_EPSILON);
  }
  const measures = buildMeasures(timeline, timeSignatures, totalBeats);

  const data: TabData = { tuning: tuning.strings.map((s) => s.pitch), measures: [] };

  // HMM inputs, accumulated as we discover new chords. The vocabulary is keyed
  // on FOLDED pitch sets (matching the fingering cache) so two chords that fold
  // to the same playable pitches share one emission column instead of
  // duplicating their fingering blocks in the state space.
  const vocabSlots = new Map<string, number>();
  const fingeringsVocab: Fingering[] = [];
  let emission: number[][] = [];
  let initial: number[] | null = null;
  const notesSequence: number[] = [];
  // INVARIANT: notesSequence and durationMaps each receive exactly one push per
  // note-event (entry.notes non-empty). The populate loop advances `ievent` under the
  // same `if (!event.notes) continue` guard, so notesSequence[i]/durationMaps[i]/chosen[i]
  // all refer to the same note-event. durationMaps[i] maps folded pitch -> durationBeats.
  const durationMaps: Map<number, number>[] = [];

  for (const measure of measures) {
    const measureLength = measure.end - measure.start;
    const events: TabEvent[] = [];

    for (const entry of measure.entries) {
      const event: TabEvent = {
        beats: entry.beats,
        measureTiming: measureLength > 0 ? (entry.beats - measure.start) / measureLength : 0,
      };
      if (input.tempo) {
        event.seconds = (entry.beats * 60) / input.tempo;
      }
      if (entry.timeSignature) {
        event.timeSignatureChange = [
          entry.timeSignature.numerator,
          entry.timeSignature.denominator,
        ];
      }

      if (entry.notes && entry.notes.length > 0) {
        event.notes = [];

        const originalPitches = [...new Set(entry.notes.map((n) => n.midi))].sort((a, b) => a - b);

        const foldedNotes = fretboard.fixOobNotes(
          originalPitches.map((p) => new Note(p)),
          false,
        );
        const vocabKey = foldedNotes
          .map((n) => n.pitch)
          .sort((a, b) => a - b)
          .join(",");
        const noteOptions = fretboard.getNoteOptions(foldedNotes);

        const durationByPitch = new Map<number, number>();
        for (const note of entry.notes) {
          const folded = foldPitchToRange(note.midi, minPitch, maxPitch);
          if (folded !== null && !durationByPitch.has(folded)) {
            durationByPitch.set(folded, note.durationBeats);
          }
        }

        let slot = vocabSlots.get(vocabKey) ?? -1;
        if (slot === -1 && noteOptions.length > 0) {
          const fingeringOptions = fretboard.getPossibleFingerings(noteOptions);
          if (fingeringOptions.length > 0) {
            slot = vocabSlots.size;
            vocabSlots.set(vocabKey, slot);
            fingeringsVocab.push(...fingeringOptions);
            // Seed the initial distribution from the first PLAYABLE chord.
            // DIVERGENCE from tuttut: the Python reference normalizes isolated
            // *difficulty* (1/easiness) here — an inversion bug that makes the
            // hardest fingering of the first chord the most probable start
            // (tab.py feeds compute_isolated_path_difficulty straight into
            // difficulties_to_probabilities, which only normalizes). We invert
            // back to easiness so the easiest fingering wins, consistent with
            // how build_transition_matrix weighs every later transition.
            if (initial === null) {
              initial = difficultiesToProbabilities(
                fingeringOptions.map((f) => 1 / computeIsolatedPathDifficulty(f, tuning)),
              );
            }
            emission = expandEmissionMatrix(emission, fingeringOptions.length);
          }
        }

        notesSequence.push(slot);
        durationMaps.push(durationByPitch);
      }

      events.push(event);
    }

    data.measures.push({ events });
  }

  // Run Viterbi over the discovered fingering vocabulary.
  // DIVERGENCE from tuttut: unplayable chords (slot -1) are excluded from the
  // observation sequence and their events render with empty `notes`. The Python
  // reference leaves -1 in the observations, which numpy negative-indexing
  // resolves to the LAST emission column — emitting phantom notes borrowed
  // from an unrelated chord. Adjacent playable chords transition directly
  // across the gap; `chosen` is scattered back by event index so alignment
  // with durationMaps/notesSequence is preserved.
  let chosen: (Fingering | undefined)[] = [];
  const playableObservations = notesSequence.filter((slot) => slot >= 0);
  if (fingeringsVocab.length > 0 && playableObservations.length > 0 && initial !== null) {
    const transition = buildTransitionMatrix(fingeringsVocab, weights, tuning);
    const initialFull = [
      ...initial,
      ...new Array<number>(transition.length - initial.length).fill(0),
    ];
    const stateIndices = viterbi(playableObservations, transition, emission, initialFull);
    let next = 0;
    chosen = notesSequence.map((slot) =>
      slot >= 0 ? fingeringsVocab[stateIndices[next++]] : undefined,
    );
  }

  // Populate notes back into the events, in the same order they were collected.
  if (chosen.length > 0) {
    let ievent = 0;
    for (const measure of data.measures) {
      for (const event of measure.events) {
        if (!event.notes) {
          continue;
        }
        const fingering = chosen[ievent];
        const durationByPitch = durationMaps[ievent];
        if (fingering) {
          for (const node of fingering) {
            event.notes.push({
              string: node.string,
              fret: node.fret,
              midi: node.pitch,
              durationBeats: durationByPitch.get(node.pitch) ?? 0,
              degree: node.degree,
              octave: node.octave,
            });
          }
        }
        ievent++;
      }
    }
  }

  return {
    data,
    toSystems: (opts) => renderAsciiTab(data, tuning, opts),
    toLines: (opts) => renderLines(data, tuning, opts),
    toAscii: (opts) => renderLines(data, tuning, opts).join("\n"),
  };
}
