import type { Tuning } from "./theory";

/** Ableton-native beats projection of a MIDI note. C4 = midi 60. */
export interface NoteModel {
  midi: number;
  startBeats: number;
  durationBeats: number;
}

export interface TimeSignature {
  numerator: number;
  denominator: number;
}

export interface TimeSignatureChange extends TimeSignature {
  startBeats: number;
}

export interface DifficultyWeights {
  b: number;
  height: number;
  length: number;
  nChangedStrings: number;
}

export type QuantizeGrid = "1/4" | "1/8" | "1/16" | "1/32";

export interface TabInput {
  /** Unmuted notes, any order (sorted internally). */
  notes: NoteModel[];
  tuning: Tuning;
  /** Piecewise measure grid. Defaults to a single 4/4 entry at beat 0. */
  timeSignatures?: TimeSignatureChange[];
  weights?: DifficultyWeights;
  /** BPM. Only used to emit optional `seconds` on each event. */
  tempo?: number;
  /** Optional onset snap before chord grouping. */
  quantizeGrid?: QuantizeGrid;
}

export interface TabNote {
  string: number;
  fret: number;
  /** Sounding pitch (string + fret), after OOB folding. */
  midi: number;
  /** Carried from the source NoteModel; drives note values & rests downstream. */
  durationBeats: number;
  /** e.g. "F#" (pretty_midi naming, including the low "C-" quirk). */
  degree: string;
  /** e.g. "4". */
  octave: string;
}

export interface TabEvent {
  beats: number;
  /** Position within the measure, normalized by measure length. Nominally in
   *  [0, 1); float-epsilon noise at measure boundaries can land a hair outside. */
  measureTiming: number;
  /** Present iff `tempo` supplied. */
  seconds?: number;
  timeSignatureChange?: [number, number];
  notes?: TabNote[];
}

export interface TabMeasure {
  events: TabEvent[];
}

export interface TabData {
  /** String pitches, thin -> thick. */
  tuning: number[];
  measures: TabMeasure[];
}

export const DEFAULT_WEIGHTS: DifficultyWeights = {
  b: 1,
  height: 1,
  length: 1,
  nChangedStrings: 1,
};

export const DEFAULT_TIME_SIGNATURE: TimeSignatureChange = {
  startBeats: 0,
  numerator: 4,
  denominator: 4,
};
