import type { FretNode, Fingering } from "./theory";

export const MAX_EDGE_DISTANCE = 6;

/**
 * Fretboard distance between two positions. Open-string targets (fret 0) always
 * return 0, matching tuttut's convention that open strings are costless to reach.
 */
export function edgeDistance(from: FretNode, to: FretNode, nstrings: number): number {
  if (to.fret === 0) {
    return 0;
  }
  return Math.hypot(from.string / nstrings - to.string / nstrings, from.fret - to.fret);
}

/** An edge is valid if the nodes are close enough AND on different strings. */
export function isEdgePossible(from: FretNode, to: FretNode, nstrings: number): boolean {
  return edgeDistance(from, to, nstrings) < MAX_EDGE_DISTANCE && from.string !== to.string;
}

/**
 * Finds all valid paths through layered note options (one layer per note).
 * Adjacent layers connect through edges satisfying isEdgePossible. Layered DFS,
 * no graph construction (port of graph_utils.find_valid_paths).
 */
export function findValidPaths(noteArrays: FretNode[][], nstrings: number): Fingering[] {
  if (noteArrays.length === 0) {
    return [];
  }

  // Adjacency between consecutive layers.
  const adjacency: Map<FretNode, FretNode[]>[] = [];
  for (let idx = 0; idx < noteArrays.length - 1; idx++) {
    const adj = new Map<FretNode, FretNode[]>();
    for (const note of noteArrays[idx]) {
      const neighbors: FretNode[] = [];
      for (const target of noteArrays[idx + 1]) {
        if (isEdgePossible(note, target, nstrings)) {
          neighbors.push(target);
        }
      }
      adj.set(note, neighbors);
    }
    adjacency.push(adj);
  }

  const paths: Fingering[] = [];
  const lastLayer = noteArrays.length - 1;

  const dfs = (layer: number, current: FretNode[]): void => {
    if (layer === lastLayer) {
      paths.push([...current]);
      return;
    }
    const tail = current[current.length - 1];
    for (const neighbor of adjacency[layer].get(tail) ?? []) {
      current.push(neighbor);
      dfs(layer + 1, current);
      current.pop();
    }
  };

  for (const start of noteArrays[0]) {
    dfs(0, [start]);
  }

  return paths;
}
